CREATE TABLE cart_owner(member_id BIGINT PRIMARY KEY) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE cart_item(id BIGINT PRIMARY KEY AUTO_INCREMENT,member_id BIGINT NOT NULL,sku_id BIGINT NOT NULL,quantity INT NOT NULL,selected BOOLEAN NOT NULL DEFAULT TRUE,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),UNIQUE(member_id,sku_id),CHECK(quantity BETWEEN 1 AND 99)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
